import{_ as e,o as a,c as t,ao as i}from"./chunks/framework.CGAfXaNK.js";const k=JSON.parse('{"title":"2D deterministic inversion","description":"","frontmatter":{},"headers":[],"relativePath":"inversion/2d_deterministic.md","filePath":"inversion/2d_deterministic.md","lastUpdated":null}'),n={name:"inversion/2d_deterministic.md"};function l(o,s,d,r,h,p){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="2D-deterministic-inversion" tabindex="-1">2D deterministic inversion <a class="header-anchor" href="#2D-deterministic-inversion" aria-label="Permalink to &quot;2D deterministic inversion {#2D-deterministic-inversion}&quot;">​</a></h1><p>A deterministic inversion starts from a model and improves it step by step until the predicted data fit the observed data. Many models can fit MT data, so we also ask for the model to be smooth and close to a reference model. The inversion balances these two goals.</p><p>MTGeophysics.jl has two deterministic algorithms:</p><ul><li><p><strong>Gauss–Newton (GN)</strong> takes few, large steps. Each step is expensive, so it suits small and medium models.</p></li><li><p><strong>Nonlinear conjugate gradients (NLCG)</strong> takes many cheap steps and uses little memory, so it suits large models.</p></li></ul><p>Both read the same six files, as ModEM does.</p><h2 id="What-you-need" tabindex="-1">What you need <a class="header-anchor" href="#What-you-need" aria-label="Permalink to &quot;What you need {#What-you-need}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">File</th><th style="text-align:left;">Contents</th></tr></thead><tbody><tr><td style="text-align:left;"><code>model.start</code></td><td style="text-align:left;">the model to start from</td></tr><tr><td style="text-align:left;"><code>data.dat</code></td><td style="text-align:left;">the observed data</td></tr><tr><td style="text-align:left;"><code>fwd.ctrl</code></td><td style="text-align:left;">mode, strike and air (see <a href="./../forward/2d">2D forward</a>)</td></tr><tr><td style="text-align:left;"><code>inv.ctrl</code></td><td style="text-align:left;">the algorithm and its settings</td></tr><tr><td style="text-align:left;"><code>cov.ctrl</code></td><td style="text-align:left;">the mask: which cells are free, fixed, air or water</td></tr><tr><td style="text-align:left;"><code>model.prior</code></td><td style="text-align:left;">the reference model for the regularisation</td></tr></tbody></table><p>You do not have to write these by hand. The <a href="./../data/mesh2d">2D mesh tool</a> writes all of them for a new data file, and the benchmark folders already contain them.</p><h2 id="Run-the-example" tabindex="-1">Run the example <a class="header-anchor" href="#Run-the-example" aria-label="Permalink to &quot;Run the example {#Run-the-example}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helpers/benchmarks_2D.jl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # writes examples/data/2D-IV</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_inv2D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GN</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # or NLCG</span></span></code></pre></div><p>To use your own files, pass all six:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_inv2D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FwdCtrl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> InvCtrl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cov.ctrl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.prior</span></span></code></pre></div><h2 id="The-inversion-control-file" tabindex="-1">The inversion control file <a class="header-anchor" href="#The-inversion-control-file" aria-label="Permalink to &quot;The inversion control file {#The-inversion-control-file}&quot;">​</a></h2><p>The example <code>examples/ctrl/2D/InvCtrl.GN</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Algorithm                         : GN</span></span>
<span class="line"><span>Initial damping factor lambda     : 1</span></span>
<span class="line"><span>Exit search when rms is less than : 1</span></span>
<span class="line"><span>Maximum number of iterations      : 20</span></span>
<span class="line"><span>Mode                              : TETM</span></span>
<span class="line"><span>Max log10 step                    : 0.5</span></span>
<span class="line"><span>Max line search steps             : 12</span></span>
<span class="line"><span>Smallness weight                  : 0.01</span></span>
<span class="line"><span>Smoothing weight y                : 1</span></span>
<span class="line"><span>Smoothing weight z                : 1</span></span>
<span class="line"><span>GN damping                        : 0.01</span></span></code></pre></div><p>The lines you will change most often are:</p><ul><li><p><code>Algorithm</code>: <code>GN</code> or <code>NLCG</code>.</p></li><li><p><code>lambda</code>: the weight of the regularisation. Larger values give smoother models that fit the data less closely.</p></li><li><p><code>Exit search when rms is less than</code>: the target RMS. An RMS of 1 means the data are fitted to within their errors.</p></li><li><p><code>Mode</code>: invert <code>TE</code>, <code>TM</code> or both (<code>TETM</code>).</p></li></ul><p>The other keys are explained in the <a href="./../developers/control_files">control file reference</a>.</p><h2 id="From-Julia" tabindex="-1">From Julia <a class="header-anchor" href="#From-Julia" aria-label="Permalink to &quot;From Julia {#From-Julia}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MTGeophysics</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Invert2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FwdCtrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;InvCtrl.GN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cov.ctrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.prior&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlotInversion2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(run; true_model_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;model.true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="What-you-get" tabindex="-1">What you get <a class="header-anchor" href="#What-you-get" aria-label="Permalink to &quot;What you get {#What-you-get}&quot;">​</a></h2><p>Everything goes into a new folder, <code>run_YYYYmmdd_HHMMSS/</code>, next to the data:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run_YYYYmmdd_HHMMSS/</span></span>
<span class="line"><span>├── model.rho       final model (can be used as a new start model)</span></span>
<span class="line"><span>├── data.pred       its predicted data</span></span>
<span class="line"><span>├── History.csv     rms and objective at every iteration</span></span>
<span class="line"><span>├── Summary.txt     final rms, stopping reason, strike</span></span>
<span class="line"><span>├── inputs/         copies of the six input files</span></span>
<span class="line"><span>└── plots/          mesh, start, final and true models, data fit, convergence</span></span></code></pre></div><p>If the data were rotated to the strike, the rotated data are also saved, as <code>data-r.dat</code>.</p><div class="tip custom-block"><p class="custom-block-title">Is the inversion done?</p><p>Look at <code>plots/</code> first. A good result fits the data (RMS close to your target) with a model that is no rougher than it needs to be. If the RMS stays high, check the data fit plot for single stations or periods that are fitted badly.</p></div><p>The equations behind both algorithms are described in <a href="./../developers/inversion2d">2D inversion theory</a>.</p>`,26)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
